const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
const labels={review:'Afventer din gennemgang',blocked:'Mangler oplysninger',sent:'Sendt',failed:'Kunne ikke starte afsendelse',uncertain:'Levering ukendt · kræver afstemning',sending:'Afsendelse behandles',pending:'Afventer afsendelse',complete:'Afsluttet',obsolete:'Tidligere version / link'};
export async function automationPanel(container,api){
 container.append(el('h2','Automatik og beskeder'),el('p','Dokumentgenerering gemmer en PDF. Afsendelse sender en besked. Kundens korrekturgodkendelse frigiver hverken produktion hos PF eller hæver penge.'));
 try{const data=await(await api('/api/pf-orders/automation-settings')).json(),form=el('form'),settings=data.settings;
 function select(key,title,options){const label=el('label',title),input=el('select');for(const [value,text] of options){const option=el('option',text);option.value=value;option.selected=settings[key]===value;input.append(option);}input.onchange=()=>settings[key]=input.value;label.append(input);form.append(label);}
 select('confirmationMail','Ordrebekræftelse efter betalingsreservation',[['automatic','Send automatisk'],['review','Gennemse og send på ordren']]);
 select('decisionReceipt','Kvittering til kunden for korrektursvar',[['automatic','Send automatisk'],['review','Send efter min gennemgang']]);
 select('staffDecisionMail','Besked til korrektur@smerch.dk om kundens svar',[['automatic','Send automatisk'],['review','Send efter min gennemgang']]);
 select('shipmentMail','Forsendelsesmail fra Smerch',[['review','Gennemse og send på ordren'],['automatic','Send automatisk med gyldigt trackinglink']]);
 select('supplierCustomerMail','PF’s direkte kundemails · skal bekræftes hos PF',[['unknown','Ikke afklaret'],['disabled','Bekræftet deaktiveret hos PF'],['enabled','PF sender selv beskeder']]);
 select('proofPublication','Ny korrektur modtaget via sikret indbakke',[['review','Gennemse og send til kunden'],['automatic','Opret kundelink og send automatisk']]);
 const label=el('label'),reminders=el('input');reminders.type='checkbox';reminders.checked=settings.proofReminders;reminders.onchange=()=>settings.proofReminders=reminders.checked;label.append(reminders,document.createTextNode('Påmind efter 48 timer · højst to påmindelser pr. aktivt kundelink'));form.append(label);
 form.append(el('p','Automatisk korrektur kræver en opsat mail-/PDF-relæforbindelse. PF’s Gateway leverer ikke selv PDF’en til denne indbakke. Forsendelsesautomatik behandler også eksisterende klargjorte beskeder. Ukendt SMTP-levering genforsøges aldrig automatisk.'));
 const save=el('button','Gem automatik'),status=el('p');status.setAttribute('role','status');form.append(save,status);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await api('/api/pf-orders/automation-settings','POST',settings);status.textContent='Indstillinger gemt.';}catch(error){status.textContent=error.message;}finally{save.disabled=false;}};container.append(form,el('h3','Forsendelsesbeskeder'));
 for(const row of data.shipments||[]){const p=el('p'),link=el('a',(labels[row.status]||row.status)+' · '+(row.to||'Modtager mangler'));link.href='/admin/pf-orders#order='+row.orderId;p.append(link);container.append(p);}if(!data.shipments?.length)container.append(el('p','Ingen forsendelsesbeskeder endnu.'));
 }catch(error){container.append(el('p',error.message));}
}
export function orderAutomationPanel(order,api){const box=el('details');box.append(el('summary','Beskeder, påmindelser og afsendelsesstatus'));const content=el('div');box.append(content);const url=`/api/pf-orders/${order.id}/automation`;
 async function load(){content.replaceChildren();try{const data=await(await api(url)).json();for(const row of [...data.shipments,...data.proofs.map(p=>({...p,proof:true})),...(data.confirmation?[{...data.confirmation,confirmation:true}]:[])]){const card=el('section'),title=el('h4',row.confirmation?'Ordrebekræftelse':row.proof?'Korrektur · version '+row.version+' · '+row.kind:'Forsendelsesmail');card.append(title,el('p',labels[row.status]||row.status),el('p',row.to||''));if(row.sentAt||row.lastSentAt)card.append(el('p','Sendt: '+new Date(row.sentAt||row.lastSentAt).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'})));if(row.text){const details=el('details'),pre=el('pre',row.text);details.append(el('summary','Vis beskedindhold'),pre);card.append(details);}for(const problem of row.problems||[])card.append(el('p',problem));if(row.error)card.append(el('p',row.error));
 if((!row.proof&&['review','failed','uncertain'].includes(row.status))||((row.proof||row.confirmation)&&['uncertain','pending'].includes(row.status))){const button=el('button',row.status==='uncertain'?'Genforsøg efter afstemning':row.status==='failed'?'Prøv igen':row.proof||row.confirmation?'Send besked':'Send forsendelsesmail');button.type='button';button.onclick=async()=>{const uncertain=row.status==='uncertain';if(uncertain&&!confirm('Har du kontrolleret mailkontoen og bekræftet, at denne besked IKKE blev sendt? Et nyt forsøg kan ellers sende en dublet.'))return;button.disabled=true;try{await api(url,'POST',{id:row.id,kind:row.confirmation?'confirmation':row.proof?'proof':'shipment',key:row.key,confirmUncertain:uncertain});await load();}catch(e){card.append(el('p',e.message));button.disabled=false;}};card.append(button);}content.append(card);}if(!data.shipments.length&&!data.proofs.length)content.append(el('p','Ingen beskeder i køen endnu.'));}catch(e){content.append(el('p',e.message));}}
 load();return box;
}
